  constexpr int CS_CONFIDENCE_THRESHOLD   = 4;
  constexpr int CPLX_CONFIDENCE_THRESHOLD = 3;

  // Global stream: how many more pos/neg accesses needed to declare a stream
  // Increase threshold so GS is only declared on clearer global behavior.
  constexpr int STREAM_DETECT_THRESHOLD = 6;

  // Saturating confidence counter max: allow a bit more hysteresis
  constexpr int CONFIDENCE_SAT_MAX = 9;

  // Throttle fill-level prefetches when MSHR is this full
  constexpr double MSHR_THRESHOLD = 0.5;
