ipcp::ip_class_t ipcp::classify_ip(int64_t old_stride, int64_t new_stride, int confidence, ip_class_t old_class)
{
  // Avoid prefetching for zero stride
  if (new_stride == 0)
    return NL;

  // Avoid very large strides (likely to pollute)
  constexpr int MAX_STRIDE_ABS = 8;
  if (std::llabs(new_stride) > MAX_STRIDE_ABS)
    return NL;

  // Strong global-stream override:
  // If a clear global direction exists and this access matches it, prefer GS.
  if (global_stream_dir != 0) {
    int dir = (new_stride > 0) ? 1 : -1;
    if (dir == global_stream_dir && std::abs(global_pos_count - global_neg_count) >= STREAM_DETECT_THRESHOLD)
      return GS;
  }

  // If stride is stable, prefer constant-stride with hysteresis.
  if (new_stride == old_stride) {
    if (confidence >= CS_CONFIDENCE_THRESHOLD)
      return CS;
    // Gentle hysteresis: if previously CS and confidence only one below threshold, keep CS.
    if (old_class == CS && confidence >= std::max(1, CS_CONFIDENCE_THRESHOLD - 1))
      return CS;
    // Otherwise retain previous class if it exists, else next-line fallback.
    return old_class == NONE ? NL : old_class;
  }

  // Stride changed: prefer CPLX if we have some confidence or if CPLX was previous class.
  if (old_class == CPLX && confidence >= 1)
    return CPLX;
  if (confidence >= CPLX_CONFIDENCE_THRESHOLD)
    return CPLX;

  // If not confident but global stream matches, fallback to GS (less aggressive than CPLX/CS).
  if (global_stream_dir != 0) {
    int dir = (new_stride > 0) ? 1 : -1;
    if (dir == global_stream_dir)
      return GS;
  }

  // Conservative fallback
  return NL;
}
